import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { methods } from "../../../constants";
import { addSectorTotals, calculateMix, summarize } from "../../../data/data";
import PivotTable from "../../table/PivotTable";

const getMixData = (database, data) => {
  data = addSectorTotals(data).map(datum => ({
    ...datum,
    sector: database.sectors[datum.sector],
    method: database.methods[datum.method]
  }));

  const methodTotals = summarize(
    data.filter(datum => ["Public", "Private"].includes(datum.sector)),
    ["method"]
  ).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  data = [...data, ...methodTotals];

  const sectorTotals = summarize(data, ["sector"]).map(datum => ({
    ...datum,
    method: "Total"
  }));

  data = [...data, ...sectorTotals];

  return calculateMix(data, "method", "sector", "Total").map(datum => ({
    ...datum,
    sector: `${datum.sector} (Mix)`
  }));
};

const getShareData = (database, data) => {
  data = addSectorTotals(data).map(datum => ({
    ...datum,
    sector: database.sectors[datum.sector],
    method: database.methods[datum.method]
  }));

  let publicPrivateSectorData = data.filter(datum =>
    ["Public", "Private"].includes(datum.sector)
  );

  const publicPrivateSectorMethodTotals = summarize(publicPrivateSectorData, [
    "method"
  ]).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  publicPrivateSectorData = [
    ...publicPrivateSectorData,
    ...publicPrivateSectorMethodTotals
  ];

  const publicPrivateSectorSectorTotals = summarize(publicPrivateSectorData, [
    "sector"
  ]).map(datum => ({
    ...datum,
    method: "Total"
  }));

  publicPrivateSectorData = [
    ...publicPrivateSectorData,
    ...publicPrivateSectorSectorTotals
  ];

  const publicPrivateSectorMethodShare = calculateMix(
    publicPrivateSectorData,
    "sector",
    "method",
    "Total"
  );

  let privateSectorData = data.filter(datum =>
    ["Private", "Private Sub", "Private Non-Sub"].includes(datum.sector)
  );

  const privateSectorSectorTotals = summarize(privateSectorData, [
    "sector"
  ]).map(datum => ({
    ...datum,
    method: "Total"
  }));

  privateSectorData = [...privateSectorData, ...privateSectorSectorTotals];

  const privateSectorMethodShare = calculateMix(
    privateSectorData,
    "sector",
    "method",
    "Private"
  ).filter(datum => datum.sector !== "Private");

  return [...publicPrivateSectorMethodShare, ...privateSectorMethodShare].map(
    datum => ({
      ...datum,
      sector: `${datum.sector} (Share)`
    })
  );
};

const getData = (database, indicatorId, areaId) => {
  const data = database.data.filter(
    datum =>
      datum.area === areaId &&
      datum.indicator === indicatorId &&
      datum.year === 2018
  );

  return [...getMixData(database, data), ...getShareData(database, data)];
};

const MethodMixAndShareTable = props => {
  const superTitles = props.showMix
    ? [
        {
          title: "",
          columnSpan: 1
        },
        {
          title: "Method Mix",
          columnSpan: 5,
          majorGroup: true,
          groupStart: true
        },
        {
          title: "Method Share",
          columnSpan: 5,
          majorGroup: true,
          groupStart: true
        }
      ].filter(title => props.showMix || title.title !== "Method Mix")
    : undefined;

  return (
    <PivotTable
      superTitles={superTitles}
      titles={[
        {
          title: "",
          columnSpan: 1
        },
        {
          key: "Total (Mix)",
          title: "",
          columnSpan: 1,
          majorGroup: true,
          groupStart: true,
          total: true
        },
        {
          key: "Sectors (Mix)",
          title: "",
          columnSpan: 2
        },
        {
          key: "Private (Mix)",
          title: "Within Private",
          columnSpan: 2,
          groupStart: true
        },
        {
          key: "Total (Share)",
          title: "",
          columnSpan: 1,
          majorGroup: true,
          groupStart: props.showMix,
          total: true
        },
        {
          key: "Sectors (Share)",
          title: "",
          columnSpan: 2
        },
        {
          key: "Private (Share)",
          title: "Within Private",
          columnSpan: 2,
          groupStart: true
        }
      ].filter(
        title => props.showMix || !title.key || !title.key.endsWith("(Mix)")
      )}
      columnKey="sector"
      columnDefinitions={[
        {
          value: "Total (Mix)",
          label: "Total",
          percentage: true,
          majorGroup: true,
          groupStart: true,
          total: true
        },
        {
          value: "Public (Mix)",
          label: "Public",
          percentage: true
        },
        {
          value: "Private (Mix)",
          label: "Private",
          percentage: true
        },
        {
          value: "Private Sub (Mix)",
          label: "Subsidized",
          percentage: true,
          groupStart: true
        },
        {
          value: "Private Non-Sub (Mix)",
          label: "Non-Subsidized",
          percentage: true
        },
        {
          value: "Total (Share)",
          label: "Total",
          percentage: true,
          majorGroup: true,
          groupStart: props.showMix,
          total: true
        },
        {
          value: "Public (Share)",
          label: "Public",
          percentage: true
        },
        {
          value: "Private (Share)",
          label: "Private",
          percentage: true
        },
        {
          value: "Private Sub (Share)",
          label: "Subsidized",
          percentage: true,
          groupStart: true
        },
        {
          value: "Private Non-Sub (Share)",
          label: "Non-Subsidized",
          percentage: true
        }
      ].slice(props.showMix ? 0 : 5)}
      rowKey="method"
      rowDefinitions={[
        ...methods.map(method => ({
          value: method
        })),
        {
          value: "Total",
          total: true
        }
      ].slice(0, props.showTotals ? undefined : -1)}
      data={getData(props.database, props.indicatorId, props.areaId)}
    />
  );
};

MethodMixAndShareTable.propTypes = {
  database: databasePropType,
  indicatorId: PropTypes.number.isRequired,
  areaId: PropTypes.number.isRequired,
  showMix: PropTypes.bool,
  showTotals: PropTypes.bool
};

MethodMixAndShareTable.defaultProps = {
  showMix: true,
  showTotals: true
};

export default MethodMixAndShareTable;
