import React, { useState } from "react";
import { databasePropType } from "../../../propTypes";
import { reportingYear } from "../../../constants";
import DataViewerFrame from "../../widgets/DataViewerFrame";
import MethodChooser from "../../choosers/MethodChooser";
import ShareOfUsersChart from "./ShareOfUsersChart";

const ShareOfUsersChartWidget = props => {
  const [methodId, setMethodId] = useState();

  return (
    <DataViewerFrame
      reference="Figure 2.2"
      title={`Share of Users, ${reportingYear}`}
      subtitle="Comparison by GNI Group and Sector"
      contentWidth={500}
      filters={[
        <MethodChooser
          id="figure-2-2"
          methods={props.database.methods}
          selectedKey={methodId}
          onChange={setMethodId}
        />
      ]}
    >
      <ShareOfUsersChart
        database={props.database}
        methodIds={methodId && new Set([methodId])}
      />
    </DataViewerFrame>
  );
};

ShareOfUsersChartWidget.propTypes = {
  database: databasePropType
};

export default ShareOfUsersChartWidget;
