import React, { useState } from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import AbsoluteChartToggleFrame from "../../widgets/AbsoluteChartToggleFrame";
import MethodChooser from "../../choosers/MethodChooser";
import ShareWithinPrivateSectorByGniGroupChart from "./ShareWithinPrivateSectorByGniGroupChart";

const ShareWithinPrivateSectorByGniGroupChartWidget = props => {
  const [methodId, setMethodId] = useState();

  return (
    <AbsoluteChartToggleFrame
      reference={props.reference}
      title={props.title}
      subtitle="Comparison by GNI Group"
      contentWidth={500}
      filters={[
        <MethodChooser
          id={props.chooserId}
          methods={props.database.methods}
          selectedKey={methodId}
          onChange={setMethodId}
        />
      ]}
      initialAbsolute={false}
    >
      <ShareWithinPrivateSectorByGniGroupChart
        indicatorId={props.indicatorId}
        database={props.database}
        methodIds={methodId && new Set([methodId])}
        tooltipFormatter={props.tooltipFormatter}
      />
    </AbsoluteChartToggleFrame>
  );
};

ShareWithinPrivateSectorByGniGroupChartWidget.propTypes = {
  database: databasePropType,
  reference: PropTypes.string.isRequired,
  title: PropTypes.string.isRequired,
  indicatorId: PropTypes.number.isRequired,
  chooserId: PropTypes.string.isRequired,
  tooltipFormatter: PropTypes.func
};

export default ShareWithinPrivateSectorByGniGroupChartWidget;
