import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { addSectorTotals, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import StackedColumnChart from "../../chart/StackedColumnChart";
import { formatValue } from "../../../utilities";

const getData = database => {
  const areaIds = new Set([14, 15, 23]);
  const sectorIds = new Set([1, 2, 3]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        datum.indicator === 1 &&
        sectorIds.has(datum.sector) &&
        datum.year >= 2021 &&
        datum.year <= 2025
    )
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area,
      sector: database.sectors[datum.sector]
    }));

  const summary = summarize(data, ["area", "sector"]);

  const areaTotals = summarize(data, ["area"]).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  return [...areaTotals, ...summary];
};

const CumulativeGapBySectorChart = props => {
  const data = getData(props.database);

  return (
    <div>
      <StackedColumnChart
        height={styleConstants.stackedBarHeight}
        reference="1.5"
        title="Cumulative Gap by GNI Group, 2021–2025"
        subtitle="Comparison by Sector"
        categories={["Total", "Donor", "Gov't", "Private"]}
        series={[
          {
            name: "LIC",
            color: styleConstants.categoryColors.gniGroupColors["LIC"],
            data: data
              .filter(datum => datum.area === "Low-Income (LIC)")
              .map(datum => datum.value)
          },
          {
            name: "L-MIC",
            color: styleConstants.categoryColors.gniGroupColors["L-MIC"],
            data: data
              .filter(datum => datum.area === "Lower-Middle-Income (L-MIC)")
              .map(datum => datum.value)
          },
          {
            name: "U-MIC",
            color: styleConstants.categoryColors.gniGroupColors["U-MIC"],
            data: data
              .filter(datum => datum.area === "Upper-Middle-Income (U-MIC)")
              .map(datum => datum.value)
          }
        ]}
        reversedLegend={true}
        plotLineValues={[0.5]}
        absolute={props.absolute}
        tooltipFormatter={function() {
          return `${this.series.name} Gap: <strong>$${formatValue(
            this.y
          )}</strong><br />Share of ${this.key} Gap: <strong>${formatValue(
            this.percentage / 100,
            true
          )}</strong>`;
        }}
      />
    </div>
  );
};

CumulativeGapBySectorChart.propTypes = {
  database: databasePropType,
  absolute: PropTypes.bool
};

export default CumulativeGapBySectorChart;
