const calculateSmallLineChartChange = point => {
  const previousPoint = point.series.data[point.point.index - 1];
  const previousY = previousPoint.y;

  const amount = point.y - previousY;

  return {
    period: `${previousPoint.x}-${point.x}`,
    amount,
    percentage: amount / previousY
  };
};

const formatSmallLineChartTooltip = point => {
  let text = `${point.series.name} Users, ${point.key}: <strong>${formatValue(
    point.y
  )}</strong>`;

  if (point.point.index > 0) {
    const change = calculateSmallLineChartChange(point);

    text += `<br />Change, ${change.period}: <strong>${formatValue(
      change.amount
    )}</strong> (<strong>${formatValue(change.percentage, true)}</strong>)`;
  }

  return text;
};

