import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { addSectorTotals, summarize } from "../../../data/data";
import PivotTable from "../../table/PivotTable";

const getData = (database, methodIds) => {
  const areaIds = new Set([14, 15, 23]);
  const sectorIds = new Set([3, 4, 5, 6]);

  methodIds =
    methodIds ||
    new Set(Object.keys(database.methods).map(id => parseInt(id, 10)));

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        datum.indicator === 4 &&
        sectorIds.has(datum.sector) &&
        methodIds.has(datum.method) &&
        datum.year === 2018
    )
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area,
      sector: database.sectors[datum.sector]
    }));

  const summary = summarize(data, ["area", "sector"]);

  const areaTotals = summarize(
    data.filter(datum => ["Public", "Private"].includes(datum.sector)),
    ["area"]
  ).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  const sectorTotals = summarize([...areaTotals, ...summary], ["sector"]).map(
    datum => ({
      ...datum,
      area: "Total"
    })
  );

  return [...areaTotals, ...summary, ...sectorTotals];
};

const UsersBySectorTable = props => (
  <PivotTable
    reference="2.1"
    caption="Users by Sector, 2018"
    subcaption="Segmented by GNI Group"
    titles={[
      {
        key: "areas",
        title: "",
        columnSpan: 1
      },
      {
        key: "total",
        title: "",
        columnSpan: 1,
        total: true
      },
      {
        key: "sectors",
        title: "",
        columnSpan: 2,
        groupEnd: true
      },
      {
        key: "privateSector",
        title: "Within Private",
        columnSpan: 2
      }
    ]}
    columnKey="sector"
    columnDefinitions={[
      {
        value: "Total",
        label: "Total",
        total: true
      },
      {
        value: "Public"
      },
      {
        value: "Private",
        groupEnd: true
      },
      {
        value: "Private Sub",
        label: "Subsidized"
      },
      {
        value: "Private Non-Sub",
        label: "Non-Subsidized"
      }
    ]}
    rowKey="area"
    rowDefinitions={[
      {
        value: "Low-Income (LIC)",
        label: "LICs"
      },
      {
        value: "Lower-Middle-Income (L-MIC)",
        label: "L-MICs"
      },
      {
        value: "Upper-Middle-Income (U-MIC)",
        label: "U-MICs"
      },
      {
        value: "Total",
        label: "Total",
        total: true
      }
    ]}
    data={getData(props.database, props.methodIds)}
  />
);

UsersBySectorTable.propTypes = {
  database: databasePropType,
  methodIds: PropTypes.object
};

export default UsersBySectorTable;
