import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { methods } from "../../../constants";
import { addSectorTotals, summarize } from "../../../data/data";
import PivotTable from "../../table/PivotTable";

const getData = (database, indicatorId, areaId) => {
  const sectorIds = new Set([3, 4, 5, 6]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        datum.area === areaId &&
        datum.indicator === indicatorId &&
        sectorIds.has(datum.sector) &&
        datum.year === 2018
    )
    .map(datum => ({
      ...datum,
      sector: database.sectors[datum.sector],
      method: database.methods[datum.method]
    }));

  const summary = summarize(data, ["sector", "method"]);

  const methodTotals = summarize(
    data.filter(datum => datum.sector !== "Private"),
    ["method"]
  ).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  const sectorTotals = summarize([...data, ...methodTotals], ["sector"]).map(
    datum => ({
      ...datum,
      method: "Total"
    })
  );

  return [...summary, ...methodTotals, ...sectorTotals];
};

const MethodVsSectorTable = props => (
  <PivotTable
    titles={[
      {
        key: "methods",
        title: "",
        columnSpan: 1
      },
      {
        key: "total",
        title: "",
        columnSpan: 1,
        total: true
      },
      {
        key: "sectors",
        title: "",
        columnSpan: 2,
        groupEnd: true
      },
      {
        key: "privateSector",
        title: "Within Private",
        columnSpan: 2
      }
    ]}
    columnKey="sector"
    columnDefinitions={[
      {
        value: "Total",
        total: true
      },
      {
        value: "Public"
      },
      {
        value: "Private",
        groupEnd: true
      },
      {
        value: "Private Sub",
        label: "Subsidized"
      },
      {
        value: "Private Non-Sub",
        label: "Non-Subsidized"
      }
    ]}
    rowKey="method"
    rowDefinitions={[
      ...methods.map(method => ({
        value: method
      })),
      {
        value: "Total",
        total: true
      }
    ].slice(0, props.showTotals ? undefined : -1)}
    data={getData(props.database, props.indicatorId, props.areaId)}
  />
);

MethodVsSectorTable.propTypes = {
  database: databasePropType,
  indicatorId: PropTypes.number.isRequired,
  areaId: PropTypes.number.isRequired,
  showTotals: PropTypes.bool
};

MethodVsSectorTable.defaultProps = {
  showTotals: true
};

export default MethodVsSectorTable;
