import * as PropTypes from "prop-types";

export const databasePropType = PropTypes.shape({
  areas: PropTypes.object.isRequired,
  indicators: PropTypes.object.isRequired,
  sectors: PropTypes.object.isRequired,
  methods: PropTypes.object.isRequired,
  data: PropTypes.array.isRequired
});

export const dataPropType = PropTypes.shape({
  databases: PropTypes.shape({
    core: databasePropType
  }),
  widgetData: PropTypes.shape({
    theme1: PropTypes.shape({
      currentSpendingBySectorTableData: PropTypes.array.isRequired
    }).isRequired
  }).isRequired
});

export const labeledValuesPropType = PropTypes.arrayOf(
  PropTypes.shape({
    label: PropTypes.string.isRequired,
    value: PropTypes.string.isRequired
  })
).isRequired;

export const titlesPropType = PropTypes.arrayOf(
  PropTypes.shape({
    key: PropTypes.string,
    title: PropTypes.string.isRequired,
    columnSpan: PropTypes.number.isRequired,
    groupStart: PropTypes.bool,
    groupEnd: PropTypes.bool,
    total: PropTypes.bool
  })
);
