import React from "react";
import * as PropTypes from "prop-types";
import { makeStyles } from "@material-ui/styles";
import classNames from "classnames";
import styleConstants from "../../styleConstants";

const useStyles = makeStyles({
  container: {
    width: props => props.width,
    backgroundColor: props => props.backgroundColor
  },
  content: {
    padding: "0 2rem 4rem"
  },
  header: {
    borderTop: `2px solid ${styleConstants.colors.theme2}`,
    marginBottom: "2rem"
  },
  reference: {
    display: "inline-block",
    backgroundColor: styleConstants.colors.theme2,
    padding: "0.5rem",
    fontSize: "0.875rem",
    fontWeight: styleConstants.fontWeights.bold,
    textTransform: "uppercase",
    color: "white"
  }
});

const Box = props => {
  const classes = useStyles(props);

  return (
    <div className={classNames("widget", classes.container)}>
      <div className={classes.header}>
        <div className={classes.reference}>{props.reference}</div>
      </div>
      <div className={classes.content}>{props.children}</div>
    </div>
  );
};

Box.propTypes = {
  width: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
  backgroundColor: PropTypes.string,
  reference: PropTypes.string.isRequired,
  children: PropTypes.oneOfType([
    PropTypes.element,
    PropTypes.arrayOf(PropTypes.element)
  ]).isRequired
};

Box.defaultProps = {
  backgroundColor: "#e9f2f5"
};

export default Box;
