import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { reportingYear } from "../../../constants";
import GniGroupBySectorChart from "../charts/GniGroupBySectorChart";
import { formatValue } from "../../../utilities";

const ShareOfUsersChart = props => (
  <GniGroupBySectorChart
    database={props.database}
    reference="2.2"
    title={`Share of Users, ${reportingYear}`}
    indicatorId={4}
    sectorIds={new Set([3, 6])}
    methodIds={props.methodIds}
    seriesNames={["Private", "Public"]}
    reversedStacks={true}
    tooltipFormatter={function() {
      return `${this.series.name} Share of ${
        this.key
      } Users: <strong>${formatValue(this.percentage / 100, true)}</strong>`;
    }}
  />
);

ShareOfUsersChart.propTypes = {
  database: databasePropType,
  methodIds: PropTypes.object
};

export default ShareOfUsersChart;
