import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { summarize } from "../../../data/data";
import PivotTable from "../../table/PivotTable";

const getGapsAsProportionOfCostShare = (data, year) =>
  Object.values(
    data
      .filter(datum => datum.year === year)
      .reduce((result, datum) => {
        result[datum.area] = {
          ...(result[datum.area] || {
            area: datum.area
          }),
          [datum.indicator]: datum.value
        };

        return result;
      }, {})
  ).map(datum => ({
    ...datum,
    indicator: `Gap as % of Cost Share (${year})`,
    value: datum[1] / datum[3]
  }));

const getData = (database, sectorIds) => {
  const areaIds = new Set([14, 15, 23]);
  const indicatorIds = new Set([1, 3]);

  sectorIds =
    sectorIds ||
    new Set(Object.keys(database.sectors).map(id => parseInt(id, 10)));

  const data = database.data
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        indicatorIds.has(datum.indicator) &&
        sectorIds.has(datum.sector) &&
        (datum.year === 2020 || datum.year === 2025)
    )
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area
    }));

  const totals = summarize(data, ["indicator", "year"]).map(datum => ({
    ...datum,
    area: "Total"
  }));

  const summary = summarize([...data, ...totals], ["area", "indicator", "year"])
    .map(datum => ({
      ...datum,
      area: datum.area
    }))
    .map(datum => ({
      ...datum,
      indicator: `${database.indicators[datum.indicator]} (${datum.year})`
    }));

  return [
    ...summary,
    ...getGapsAsProportionOfCostShare(data, 2020),
    ...getGapsAsProportionOfCostShare(data, 2025),
    ...totals,
    ...getGapsAsProportionOfCostShare(totals, 2020),
    ...getGapsAsProportionOfCostShare(totals, 2025)
  ];
};

const ProjectedFundingGapsByGniGroupTable = props => (
  <PivotTable
    titles={[
      {
        title: "",
        columnSpan: 1
      },
      {
        title: "2020",
        columnSpan: 3,
        groupStart: true
      },
      {
        title: "2025",
        columnSpan: 3,
        groupStart: true
      }
    ]}
    columnKey="indicator"
    columnDefinitions={[
      {
        value: "Cost Share (2020)",
        label: "Cost Share",
        groupStart: true
      },
      {
        value: "Gap (2020)",
        label: "Gap"
      },
      {
        value: "Gap as % of Cost Share (2020)",
        label: "Gap as % of<br />Cost Share",
        percentage: true
      },
      {
        value: "Cost Share (2025)",
        label: "Cost Share",
        groupStart: true
      },
      {
        value: "Gap (2025)",
        label: "Gap"
      },
      {
        value: "Gap as % of Cost Share (2025)",
        label: "Gap as % of<br />Cost Share",
        percentage: true
      }
    ]}
    rowKey="area"
    rowDefinitions={[
      {
        value: "Low-Income (LIC)",
        label: "LIC"
      },
      {
        value: "Lower-Middle-Income (L-MIC)",
        label: "L-MIC"
      },
      {
        value: "Upper-Middle-Income (U-MIC)",
        label: "U-MIC"
      },
      {
        value: "Total",
        total: true
      }
    ]}
    data={getData(props.database, props.sectorIds)}
  />
);

ProjectedFundingGapsByGniGroupTable.propTypes = {
  database: databasePropType,
  sectorIds: PropTypes.object
};

export default ProjectedFundingGapsByGniGroupTable;
