import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { methods, reportingYear } from "../../../constants";
import { addSectorTotals, orderByValues, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import StackedColumnChart from "../../chart/StackedColumnChart";

const getData = (database, areaId, sectorId) => {
  const indicatorIds = new Set([4, 6]);

  const sectorIds = new Set(sectorId ? [sectorId] : [3, 6]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        datum.area === areaId &&
        indicatorIds.has(datum.indicator) &&
        sectorIds.has(datum.sector) &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      indicator: database.indicators[datum.indicator],
      method: database.methods[datum.method]
    }));

  return summarize(data, ["indicator", "method"]);
};

const MethodMixOfUseVsCostChart = props => {
  const data = getData(props.database, props.areaId, props.sectorId);

  return (
    <div>
      <StackedColumnChart
        height={styleConstants.stackedBarHeight}
        categories={["User", "Cost"]}
        series={methods.map(method => ({
          name: method,
          color: styleConstants.categoryColors.methodColors[method],
          data: orderByValues(
            data.filter(datum => datum.method === method),
            ["User", "Cost"],
            "indicator"
          ).map(datum => datum.value)
        }))}
        reversedLegend={true}
        legendPosition={props.legendPosition}
        tooltipFormatter={props.tooltipFormatter}
      />
    </div>
  );
};

MethodMixOfUseVsCostChart.propTypes = {
  database: databasePropType,
  areaId: PropTypes.number.isRequired,
  sectorId: PropTypes.number,
  legendPosition: PropTypes.string,
  tooltipFormatter: PropTypes.func
};

export default MethodMixOfUseVsCostChart;
