import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { reportingYear } from "../../../constants";
import { getGniGroupCode } from "../../../utilities";
import {
  addSectorTotals,
  calculateMix,
  orderByValues,
  summarize
} from "../../../data/data";
import styleConstants from "../../../styleConstants";
import MosaicChart from "../../chart/MosaicChart";

const getSeries = (database, data, seriesNames) => {
  const areaIds = new Set([14, 15, 23]);

  data = data
    .filter(datum => areaIds.has(datum.area))
    .map(datum => {
      const area = getGniGroupCode(database.areas[datum.area].area);

      let sector = database.sectors[datum.sector];

      sector =
        {
          "Private Sub": "Private Subsidized",
          "Private Non-Sub": "Private Non-Subsidized"
        }[sector] || sector;

      return {
        ...datum,
        area,
        sector
      };
    });

  const totalSpend = summarize(data, [])[0].value;

  const areaMix = summarize(data, ["area"])
    .map(datum => ({
      ...datum,
      sector: "Total",
      value: datum.value / totalSpend
    }))
    .reduce((result, datum) => {
      result[datum.area] = datum.value;

      return result;
    }, {});

  const areaTotals = summarize(data, ["area"]).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  const summary = summarize(data, ["area", "sector"]);

  const sectorMix = calculateMix(
    [...summary, ...areaTotals],
    "sector",
    "area",
    "Total"
  ).filter(datum => datum.sector !== "Total");

  return seriesNames.map(seriesName => ({
    name: seriesName.replace("Private ", ""),
    color: styleConstants.categoryColors.sectorColors[seriesName],
    data: orderByValues(
      sectorMix.filter(datum => datum.sector === seriesName),
      ["LIC", "L-MIC", "U-MIC"],
      "area"
    ).map(datum => [datum.area, datum.value * 100, areaMix[datum.area] * 100])
  }));
};

const GniGroupBySectorChart = props => {
  const methodIds =
    props.methodIds ||
    new Set(Object.keys(props.database.methods).map(id => parseInt(id, 10)));

  const data = addSectorTotals(props.database.data).filter(
    datum =>
      datum.indicator === props.indicatorId &&
      props.sectorIds.has(datum.sector) &&
      methodIds.has(datum.method) &&
      (!datum.year || datum.year === reportingYear)
  );

  const series = getSeries(props.database, data, props.seriesNames);

  return (
    <MosaicChart
      xAxisTitle="Share by GNI Group"
      yAxisTitle="Share by Sector"
      series={series}
      reversedStacks={props.reversedStacks}
      legendPosition="right"
      legendWidth={props.legendWidth}
      tooltipFormatter={props.tooltipFormatter}
    />
  );
};

GniGroupBySectorChart.propTypes = {
  database: databasePropType,
  indicatorId: PropTypes.number.isRequired,
  sectorIds: PropTypes.object.isRequired,
  methodIds: PropTypes.object,
  seriesNames: PropTypes.arrayOf(PropTypes.string).isRequired,
  reversedStacks: PropTypes.bool,
  legendWidth: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
  tooltipFormatter: PropTypes.func
};

export default GniGroupBySectorChart;
