import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { methods, reportingYear } from "../../../constants";
import { addSectorTotals, orderByValues, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import MirroredBarChart from "../../chart/MirroredBarChart";
import { formatValue } from "../../../utilities";

const getData = (database, areaId) => {
  const sectorIds = new Set([4, 5]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        datum.area === areaId &&
        datum.indicator === 4 &&
        sectorIds.has(datum.sector) &&
        datum.method !== 2 &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      sector: database.sectors[datum.sector],
      method: database.methods[datum.method]
    }));

  return summarize(data, ["sector", "method"]);
};

const ShareOfUsersWithinPrivateSectorByMethodChart = props => {
  const data = getData(props.database, props.areaId);

  return (
    <MirroredBarChart
      height={200}
      headerOffset={95}
      categories={methods}
      series={[
        {
          name: "Private (Subsidized)",
          color:
            styleConstants.categoryColors.sectorColors["Private Subsidized"],
          data: orderByValues(
            data.filter(datum => datum.sector === "Private Sub"),
            methods,
            "method"
          ).map(datum => -datum.value)
        },
        {
          name: "Private (Non-Subsidized)",
          color:
            styleConstants.categoryColors.sectorColors[
              "Private Non-Subsidized"
            ],
          data: orderByValues(
            data.filter(datum => datum.sector === "Private Non-Sub"),
            methods,
            "method"
          ).map(datum => datum.value)
        }
      ]}
      legendPosition="none"
      absolute={props.absolute}
      tooltipFormatter={function() {
        return `${this.series.name} ${this.key} Users: <strong>${formatValue(
          Math.abs(this.y)
        )}</strong><br />Share of Private ${
          this.key
        } Users: <strong>${formatValue(
          Math.abs(this.percentage) / 100,
          true
        )}</strong>`;
      }}
    />
  );
};

ShareOfUsersWithinPrivateSectorByMethodChart.propTypes = {
  database: databasePropType,
  areaId: PropTypes.number.isRequired,
  absolute: PropTypes.bool
};

export default ShareOfUsersWithinPrivateSectorByMethodChart;
