import React from "react";
import * as PropTypes from "prop-types";
import { withStyles } from "@material-ui/styles";

const styles = {
  boxWithText: {
    flex: 1,
    paddingRight: "1rem"
  },
  container: {
    display: "flex",
    alignItems: "center"
  },
  figure: {
    flex: 1,
    paddingLeft: "1rem"
  },
  text: {
    paddingLeft: "2rem"
  }
};

const FigureWithBox = props => (
  <div className={props.classes.container}>
    <div className={props.classes.boxWithText}>
      <div className={props.classes.text}>{props.children}</div>
      {props.box}
    </div>

    <div className={props.classes.figure}>{props.figure}</div>
  </div>
);

FigureWithBox.propTypes = {
  figure: PropTypes.node.isRequired,
  box: PropTypes.node.isRequired,
  children: PropTypes.oneOfType([
    PropTypes.node,
    PropTypes.arrayOf(PropTypes.node)
  ]).isRequired
};

export default withStyles(styles)(FigureWithBox);
