import React from "react";
import { withStyles } from "@material-ui/styles";
import classNames from "classnames";
import Box from "../../box/Box";

const styles = {
  country: {
    marginLeft: "2rem"
  },
  frame: {
    display: "flex"
  },
  item: {
    flex: 1
  }
};

const CostVsUsersAtCountryLevelBox = ({ classes }) => (
  <Box reference="Box 4.2">
    <h4>Costs versus Users at the Country Level</h4>

    <div className={classes.frame}>
      <div className={classes.item}>
        <p>
          The countries with the most users are often not the countries with the
          largest consumption costs due to differences in method mix and
          differences in the unit prices paid for commodities.
        </p>
        <p>
          The clearest example of the disconnect between costs and users can be
          seen when contrasting India and Brazil:
        </p>
      </div>

      <div className={classNames(classes.frame, classes.item)}>
        <p className={classNames(classes.item, classes.country)}>
          <strong>India</strong> accounts for 30% of users across the 135 LMICs
          but makes up only 7% of consumption costs: this is due to high levels
          of LAPM users in India, many of whom have low or no consumption cost
          associated with them.
        </p>
        <p className={classNames(classes.item, classes.country)}>
          <strong>Brazil</strong> accounts for only 8% of users across the 135
          LMICs but makes up 30% of consumption costs: This is due to several
          factors, including a relatively large number of pill users in Brazil
          (14.3 million) and higher prices for commodities in Latin American
          countries.
        </p>
      </div>
    </div>
  </Box>
);

export default withStyles(styles)(CostVsUsersAtCountryLevelBox);
