import React, { useState } from "react";
import { databasePropType } from "../../../propTypes";
import { reportingYear } from "../../../constants";
import DataViewerFrame from "../../widgets/DataViewerFrame";
import MethodChooser from "../../choosers/MethodChooser";
import ShareOfConsumptionCostsVsUsersBySectorChart from "./ShareOfConsumptionCostsVsUsersBySectorChart";

const ShareOfConsumptionCostsVsUsersBySectorChartWidget = props => {
  const [methodId, setMethodId] = useState();

  return (
    <DataViewerFrame
      reference="Figure 4.7"
      title={`Share of Consumption Costs versus Users by Sector, ${reportingYear}`}
      subtitle="Comparison by GNI Group"
      contentWidth={650}
      filters={[
        <MethodChooser
          id="figure-4-7"
          methods={props.database.methods}
          selectedKey={methodId}
          onChange={setMethodId}
        />
      ]}
    >
      <ShareOfConsumptionCostsVsUsersBySectorChart
        database={props.database}
        indicator={6}
        methodIds={methodId && new Set([methodId])}
      />
    </DataViewerFrame>
  );
};

ShareOfConsumptionCostsVsUsersBySectorChartWidget.propTypes = {
  database: databasePropType
};

export default ShareOfConsumptionCostsVsUsersBySectorChartWidget;
