import React, { useState } from "react";
import { databasePropType } from "../../../propTypes";
import { defaultAreaId } from "../../../constants";
import AreaChooser from "../../choosers/AreaChooser";
import ChangeInMethodMixChart from "./ChangeInMethodMixChart";
import DataViewerFrame from "../../widgets/DataViewerFrame";

const ChangeInMethodMixChartWidget = props => {
  const [areaId, setAreaId] = useState(defaultAreaId);

  return (
    <DataViewerFrame
      reference="Figure 5.2"
      title="Percentage Point Change in Method Mix, 2020–2030"
      filters={[
        <AreaChooser
          id="figure-5-2"
          label="Select Country or Country Group"
          areas={props.database.areas}
          includeCountries={true}
          selectedKey={areaId}
          onChange={setAreaId}
        />
      ]}
    >
      <ChangeInMethodMixChart database={props.database} areaId={areaId} />
    </DataViewerFrame>
  );
};

ChangeInMethodMixChartWidget.propTypes = {
  database: databasePropType
};

export default ChangeInMethodMixChartWidget;
