import React, { useState } from "react";
import { databasePropType } from "../../../propTypes";
import DataViewerFrame from "../../widgets/DataViewerFrame";
import MethodChooser from "../../choosers/MethodChooser";
import UsersBySectorTable from "./UsersBySectorTable";

const UsersBySectorTableWidget = props => {
  const [methodId, setMethodId] = useState();

  return (
    <DataViewerFrame
      reference="Table 2.1"
      title="Users by Sector, 2018"
      subtitle="Segmented by GNI Group"
      filters={[
        <MethodChooser
          id="table-2-1"
          methods={props.database.methods}
          selectedKey={methodId}
          onChange={setMethodId}
        />
      ]}
    >
      <UsersBySectorTable
        database={props.database}
        methodIds={methodId && new Set([methodId])}
      />
    </DataViewerFrame>
  );
};

UsersBySectorTableWidget.propTypes = {
  database: databasePropType
};

export default UsersBySectorTableWidget;
