import React, { useEffect, useState } from "react";
import { reportingYear } from "../constants";
import { addSectorTotals, filterByYear } from "../data/data";
import { calculateTheme1CurrentSpendingBySectorTableData } from "../data/widgetData";
import App from "../components/App";

const marshallData = database => {
  const reportingYearData = filterByYear(database.data, reportingYear);

  const databases = {
    core: database,
    reportingYear: {
      ...database,
      data: reportingYearData
    },
    allSectorTotals: {
      ...database,
      data: addSectorTotals(database.data)
    }
  };

  return {
    databases,
    widgetData: {
      theme1: {
        currentSpendingBySectorTableData: calculateTheme1CurrentSpendingBySectorTableData(
          databases
        )
      }
    }
  };
};

const AppContainer = () => {
  const [data, setData] = useState();

  useEffect(() => {
    async function fetchData() {
      const response = await fetch(`${process.env.PUBLIC_URL}/database.json`);
      const database = await response.json();

      setData(marshallData(database));
    }

    fetchData().catch(console.error);
  }, []);

  return <App data={data} />;
};

export default AppContainer;
