import React, { useState } from "react";
import { databasePropType } from "../../../propTypes";
import { defaultAreaId, reportingYear } from "../../../constants";
import AreaChooser from "../../choosers/AreaChooser";
import DataViewerFrame from "../../widgets/DataViewerFrame";
import MethodMixOfUseVsCostChart from "./MethodMixOfUseVsCostChart";
import SectorChooser from "../../choosers/SectorChooser";
import { formatValue } from "../../../utilities";

const MethodMixOfUseVsCostBySectorChartWidget = props => {
  const [sectorId, setSectorId] = useState(6);
  const [areaId, setAreaId] = useState(defaultAreaId);

  return (
    <DataViewerFrame
      reference="Figure 4.4"
      title={`Method Mix of Use versus Cost, ${reportingYear}`}
      subtitle={sectorId && `Within ${props.database.sectors[sectorId]} Sector`}
      contentWidth={300}
      filters={[
        <SectorChooser
          id="figure-4-4-sector"
          sectorIds={new Set([3, 6])}
          selectedKey={sectorId}
          onChange={setSectorId}
        />,
        <AreaChooser
          id="figure-4-4-area"
          label="Select Country or Country Group"
          areas={props.database.areas}
          includeCountries={true}
          selectedKey={areaId}
          onChange={setAreaId}
        />
      ]}
    >
      <MethodMixOfUseVsCostChart
        database={props.database}
        areaId={areaId}
        sectorId={sectorId}
        tooltipFormatter={function() {
          return `${this.series.name} Share of ${
            this.key
          } Mix: <strong>${formatValue(
            Math.abs(this.percentage) / 100,
            true
          )}</strong>`;
        }}
      />
    </DataViewerFrame>
  );
};

MethodMixOfUseVsCostBySectorChartWidget.propTypes = {
  database: databasePropType
};

export default MethodMixOfUseVsCostBySectorChartWidget;
