const mapColors = {
  LIC: styleConstants.colors.theme2,
  LICND: styleConstants.colors.theme2,
  LMIC: styleConstants.colors.theme4,
  LMICND: "transparent",
  O: "transparent",
  UMIC: styleConstants.colors.theme5,
  UMICND: styleConstants.colors.theme5,
  UMICNI: styleConstants.colors.theme5
};

const pattern1 = "M 0 0 L 5 5 M 4 -1 L 6 1 M -1 4 L 1 6";
const pattern2 = "M 5 0 L 0 5 M 1 -1 L -1 1 M 6 4 L 4 6";

const createMapPattern = path => ({
  path: {
    d: path,
    strokeWidth: 1
  },
  width: 5,
  height: 5
});

const mapPatterns = {
  LICND: createMapPattern(pattern1),
  UMICND: createMapPattern(pattern1),
  UMICNI: createMapPattern(pattern2)
};

export const toolbarHeight = "80px";

export const darken = (color, hslPercent) => lighten(color, -hslPercent);

export const lighten = (color, hslPercent) => {
  const chromaColor = chroma(color);

  return chromaColor.set("hsl.l", chromaColor.get("hsl.l") + hslPercent).hex();
};

