import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { reportingYear } from "../../../constants";
import { formatValue, getGniGroupCode } from "../../../utilities";
import { orderByValues, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import StackedColumnChart from "../../chart/StackedColumnChart";

const getData = (database, methodId) => {
  const areaIds = new Set([14, 15, 23]);
  const indicatorIds = new Set([4, 6]);

  const methodIds = new Set(
    methodId
      ? [methodId]
      : Object.keys(database.methods).map(id => parseInt(id, 10))
  );

  let data = database.data
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        indicatorIds.has(datum.indicator) &&
        methodIds.has(datum.method) &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      indicator: database.indicators[datum.indicator],
      area: database.areas[datum.area].area
    }));

  data = data.map(datum => ({
    ...datum,
    area: getGniGroupCode(datum.area)
  }));

  return summarize(data, ["area", "indicator"]);
};

const ShareOfUsersVsCostChart = props => {
  const gniGroups = ["LIC", "L-MIC", "U-MIC"];

  const data = getData(props.database, props.methodId);

  return (
    <div>
      <StackedColumnChart
        height={styleConstants.stackedBarHeight}
        categories={["User", "Cost"]}
        series={gniGroups.map(gniGroup => ({
          name: gniGroup,
          color: styleConstants.categoryColors.gniGroupColors[gniGroup],
          data: orderByValues(
            data.filter(datum => datum.area === gniGroup),
            gniGroups,
            "area"
          ).map(datum => datum.value)
        }))}
        reversedLegend={true}
        tooltipFormatter={function() {
          return `${this.series.name} Share of ${
            this.key
          } Mix: <strong>${formatValue(
            Math.abs(this.percentage) / 100,
            true
          )}</strong>`;
        }}
      />
    </div>
  );
};

ShareOfUsersVsCostChart.propTypes = {
  database: databasePropType,
  methodId: PropTypes.number
};

export default ShareOfUsersVsCostChart;
