import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { methods, reportingYear } from "../../../constants";
import { addSectorTotals, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import StackedColumnChart from "../../chart/StackedColumnChart";

const getData = (database, indicatorId, sectorId) => {
  const areaIds = new Set([14, 15, 23]);

  const sectorIds = new Set(sectorId ? [sectorId] : [3, 6]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        datum.indicator === indicatorId &&
        sectorIds.has(datum.sector) &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area,
      method: database.methods[datum.method]
    }));

  return summarize(data, ["area", "method"]);
};

const MethodMixChart = props => {
  const data = getData(props.database, props.indicatorId, props.sectorId);

  return (
    <div>
      <StackedColumnChart
        height={styleConstants.stackedBarHeight}
        categories={["LIC", "L-MIC", "U-MIC"]}
        series={methods.map(method => ({
          name: method,
          color: styleConstants.categoryColors.methodColors[method],
          data: data
            .filter(datum => datum.method === method)
            .map(datum => datum.value)
        }))}
        reversedLegend={true}
        absolute={props.absolute}
        tooltipFormatter={props.tooltipFormatter}
      />
    </div>
  );
};

MethodMixChart.propTypes = {
  database: databasePropType,
  indicatorId: PropTypes.number.isRequired,
  sectorId: PropTypes.oneOf([3, 6]),
  absolute: PropTypes.bool,
  tooltipFormatter: PropTypes.func
};

export default MethodMixChart;
