import React from "react";
import * as PropTypes from "prop-types";
import ItemChooser from "./ItemChooser";

const SectorChooser = props => (
  <ItemChooser
    id={props.id}
    label={props.label}
    items={[
      {
        value: "-1",
        label: "All sectors"
      },
      {
        value: "6",
        label: "Public"
      },
      {
        value: "1",
        label: "Public (Donor)"
      },
      {
        value: "2",
        label: "Public (Government)"
      },
      {
        value: "3",
        label: "Private"
      }
    ].filter(
      sector =>
        sector.value === "-1" || props.sectorIds.has(parseInt(sector.value, 10))
    )}
    value={props.selectedKey ? props.selectedKey.toString() : "-1"}
    onChange={value => {
      props.onChange(value === "-1" ? undefined : parseInt(value, 10));
    }}
  />
);

SectorChooser.propTypes = {
  id: PropTypes.string.isRequired,
  label: PropTypes.string,
  sectorIds: PropTypes.object.isRequired,
  selectedKey: PropTypes.number,
  onChange: PropTypes.func.isRequired
};

SectorChooser.defaultProps = {
  label: "Select Sector",
  includeAllSectors: true
};

export default SectorChooser;
