import React from "react";
import * as PropTypes from "prop-types";
import { makeStyles } from "@material-ui/styles";
import styleConstants from "../../styleConstants";
import Box from "../box/Box";

const useStyles = makeStyles({
  absoluteToggle: {
    marginLeft: props => (props.filters ? "2rem" : undefined)
  },
  container: {
    width: props => props.width,
    backgroundColor: "white",
    paddingBottom: "2rem"
  },
  contentContainer: {
    display: "flex",
    flexDirection: "row",
    justifyContent: "center"
  },
  controls: {
    marginTop: "2rem",
    display: "flex",
    justifyContent: "center",
    alignItems: "center"
  },
  dataViewer: {
    width: props => props.contentWidth
  },
  dataViewerContainer: {
    marginTop: "2rem",
    display: "flex",
    justifyContent: "center"
  },
  filter: {
    marginTop: "1rem"
  },
  filters: {
    flex: 1
  },
  header: {
    borderTop: `2px solid ${styleConstants.colors.theme2}`,
    marginBottom: "2rem"
  },
  reference: {
    display: "inline-block",
    backgroundColor: styleConstants.colors.theme2,
    padding: "0.5rem",
    fontSize: "0.875rem",
    fontWeight: styleConstants.fontWeights.bold,
    textTransform: "uppercase",
    color: "white"
  },
  title: {
    fontSize: "1rem",
    fontWeight: styleConstants.fontWeights.bold
  },
  subtitle: {
    fontSize: "1rem",
    fontWeight: styleConstants.fontWeights.book,
    fontStyle: "italic",
    color: styleConstants.colors.dark
  }
});

const DataViewerFrame = props => {
  const classes = useStyles(props);

  return (
    <Box
      width={props.width}
      backgroundColor="white"
      reference={props.reference}
    >
      <div className={classes.contentContainer}>
        <div>
          <div className={classes.title}>{props.title}</div>
          <div className={classes.subtitle}>{props.subtitle}</div>
          <div className={classes.dataViewerContainer}>
            <div className={classes.dataViewer}>{props.children}</div>
          </div>
          {(props.filters || props.absoluteToggle) && (
            <div className={classes.controls}>
              <div className={classes.filters}>
                {props.filters &&
                  props.filters.map((filter, index) => (
                    <div
                      key={filter.props.id}
                      className={index ? classes.filter : undefined}
                    >
                      {filter}
                    </div>
                  ))}
              </div>
              {props.absoluteToggle && (
                <div className={classes.absoluteToggle}>
                  {props.absoluteToggle}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </Box>
  );
};

DataViewerFrame.propTypes = {
  width: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
  reference: PropTypes.string.isRequired,
  title: PropTypes.string.isRequired,
  subtitle: PropTypes.string,
  contentWidth: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
  children: PropTypes.element.isRequired,
  filters: PropTypes.arrayOf(PropTypes.element),
  absoluteToggle: PropTypes.element
};

DataViewerFrame.defaultProps = {
  contentWidth: "100%"
};

export default DataViewerFrame;
