import React from "react";
import * as PropTypes from "prop-types";
import { withStyles } from "@material-ui/styles";

const styles = {
  column: {
    flex: 1,
    padding: "0 1rem",

    "&:first-child": {
      paddingLeft: "2rem"
    }
  },
  container: {
    display: "flex"
  }
};

const TwoColumns = props => (
  <div className={props.classes.container}>
    <div className={props.classes.column}>{props.leftColumn}</div>
    <div className={props.classes.column}>{props.rightColumn}</div>
  </div>
);

TwoColumns.propTypes = {
  leftColumn: PropTypes.node.isRequired,
  rightColumn: PropTypes.node.isRequired
};

export default withStyles(styles)(TwoColumns);
