import React from "react";
import * as PropTypes from "prop-types";
import { withStyles } from "@material-ui/styles";
import Box from "./Box";
import styleConstants from "../../styleConstants";

const styles = {
  title: {
    marginBottom: "2rem",
    fontSize: "1rem",
    fontWeight: styleConstants.fontWeights.bold
  },
  content: {
    textAlign: "center"
  }
};

const InfographicBox = props => (
  <Box reference={props.reference} backgroundColor="white">
    <div className={props.classes.title}>{props.title}</div>
    <div className={props.classes.content}>{props.children}</div>
  </Box>
);

InfographicBox.propTypes = {
  reference: PropTypes.string.isRequired,
  title: PropTypes.string.isRequired,
  children: PropTypes.node.isRequired
};

export default withStyles(styles)(InfographicBox);
