import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { methods, reportingYear } from "../../../constants";
import { formatValue } from "../../../utilities";
import { addSectorTotals, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import StackedColumnChart from "../../chart/StackedColumnChart";

const getData = (database, areaId) => {
  const sectorIds = new Set([3, 6]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        datum.area === areaId &&
        datum.indicator === 6 &&
        sectorIds.has(datum.sector) &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      sector: database.sectors[datum.sector],
      method: database.methods[datum.method]
    }));

  return summarize(data, ["sector", "method"]);
};

const ConsumptionCostChart = props => {
  const data = getData(props.database, props.areaId);

  return (
    <div>
      <StackedColumnChart
        height={styleConstants.stackedBarHeight}
        categories={["Public", "Private"]}
        series={methods.map(method => ({
          name: method,
          color: styleConstants.categoryColors.methodColors[method],
          data: data
            .filter(datum => datum.method === method)
            .map(datum => datum.value)
        }))}
        reversedLegend={true}
        absolute={props.absolute}
        tooltipFormatter={function() {
          return `${this.key} ${this.series.name} Costs: <strong>${formatValue(
            Math.abs(this.y)
          )}</strong><br />Share of ${this.key} Costs: <strong>${formatValue(
            Math.abs(this.percentage) / 100,
            true
          )}</strong>`;
        }}
      />
    </div>
  );
};

ConsumptionCostChart.propTypes = {
  database: databasePropType,
  areaId: PropTypes.number.isRequired,
  absolute: PropTypes.bool
};

export default ConsumptionCostChart;
