import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { reportingYear } from "../../../constants";
import { addSectorTotals, orderByValues, summarize } from "../../../data/data";
import styleConstants from "../../../styleConstants";
import MirroredBarChart from "../../chart/MirroredBarChart";

const getData = (database, indicatorId, methodIds) => {
  const areaIds = new Set([14, 15, 23]);
  const sectorIds = new Set([4, 5]);

  methodIds =
    methodIds ||
    new Set(Object.keys(database.methods).map(id => parseInt(id, 10)));

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        datum.indicator === indicatorId &&
        sectorIds.has(datum.sector) &&
        methodIds.has(datum.method) &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area,
      sector: database.sectors[datum.sector]
    }));

  return summarize(data, ["area", "sector"]);
};

const ShareWithinPrivateSectorByGniGroupChart = props => {
  const areas = [
    "Low-Income (LIC)",
    "Lower-Middle-Income (L-MIC)",
    "Upper-Middle-Income (U-MIC)"
  ];

  const data = getData(props.database, props.indicatorId, props.methodIds);

  return (
    <MirroredBarChart
      height={125}
      headerOffset={52}
      categories={["LIC", "L-MIC", "U-MIC"]}
      series={[
        {
          name: "Private (Subsidized)",
          color:
            styleConstants.categoryColors.sectorColors["Private Subsidized"],
          data: orderByValues(
            data.filter(datum => datum.sector === "Private Sub"),
            areas,
            "area"
          ).map(datum => -datum.value)
        },
        {
          name: "Private (Non-Subsidized)",
          color:
            styleConstants.categoryColors.sectorColors[
              "Private Non-Subsidized"
            ],
          data: orderByValues(
            data.filter(datum => datum.sector === "Private Non-Sub"),
            areas,
            "area"
          ).map(datum => datum.value)
        }
      ]}
      legendPosition="none"
      absolute={props.absolute}
      tooltipFormatter={props.tooltipFormatter}
    />
  );
};

ShareWithinPrivateSectorByGniGroupChart.propTypes = {
  database: databasePropType,
  indicatorId: PropTypes.number.isRequired,
  methodIds: PropTypes.object,
  absolute: PropTypes.bool,
  tooltipFormatter: PropTypes.func
};

export default ShareWithinPrivateSectorByGniGroupChart;
