import React, { useState } from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { defaultAreaId } from "../../../constants";
import AreaChooser from "../../choosers/AreaChooser";
import ChangeByMethodChart from "./ChangeByMethodChart";
import DataViewerFrame from "../../widgets/DataViewerFrame";

const ChangeByMethodChartWidget = props => {
  const [areaId, setAreaId] = useState(defaultAreaId);

  return (
    <DataViewerFrame
      reference={props.reference}
      title={props.title}
      subtitle={props.subtitle}
      filters={[
        <AreaChooser
          id={props.chooserId}
          label="Select Country or Country Group"
          areas={props.database.areas}
          includeCountries={true}
          selectedKey={areaId}
          onChange={setAreaId}
        />
      ]}
    >
      <ChangeByMethodChart
        database={props.database}
        yAxisTitle={props.yAxisTitle}
        areaId={areaId}
        indicatorId={props.indicatorId}
        tooltipFormatter={props.tooltipFormatter}
      />
    </DataViewerFrame>
  );
};

ChangeByMethodChartWidget.propTypes = {
  database: databasePropType,
  reference: PropTypes.string.isRequired,
  title: PropTypes.string.isRequired,
  subtitle: PropTypes.string,
  yAxisTitle: PropTypes.string,
  indicatorId: PropTypes.number.isRequired,
  chooserId: PropTypes.string.isRequired,
  tooltipFormatter: PropTypes.func
};

export default ChangeByMethodChartWidget;
