import React from "react";
import * as PropTypes from "prop-types";
import { databasePropType } from "../../../propTypes";
import { getGniGroupCode } from "../../../utilities";
import { getChangeData } from "../../../data/changeData";
import { withStyles } from "@material-ui/core";
import styleConstants from "../../../styleConstants";
import PanelChart from "../../chart/PanelChart";
import SmallLineChart from "../../chart/SmallLineChart";

const styles = {
  smallLineChart: {
    padding: "0 5px",
    border: "0px solid #eee"
  }
};

const getData = (database, indicatorId, methodId) => {
  const areaIds = new Set([14, 15, 23]);

  const methodIds = new Set(
    methodId
      ? [methodId]
      : Object.keys(database.methods).map(id => parseInt(id, 10))
  );

  return getChangeData(
    database.data.filter(
      datum =>
        areaIds.has(datum.area) &&
        datum.indicator === indicatorId &&
        methodIds.has(datum.method)
    ),
    "area"
  )
    .map(datum => ({
      ...datum,
      area: datum.area !== "Total" ? database.areas[datum.area].area : "Total"
    }))
    .filter(datum => datum.area !== "Total");
};

const ChangeByGniGroupChart = props => {
  const data = getData(props.database, props.indicatorId, props.methodId);

  const yearData = data.filter(datum => !isNaN(datum.year));

  const maximumValue = Math.max(...yearData.map(datum => datum.value));

  return (
    <PanelChart>
      {[
        "Low-Income (LIC)",
        "Lower-Middle-Income (L-MIC)",
        "Upper-Middle-Income (U-MIC)"
      ].map((area, index) => {
        const chartTitle = getGniGroupCode(area);

        const series = {
          name: chartTitle,
          color: styleConstants.categoryColors.gniGroupColors[chartTitle],
          data: yearData
            .filter(datum => datum.area === area)
            .map(datum => ({
              ...datum,
              year: parseInt(datum.year, 10)
            }))
            .sort((a, b) => a.year - b.year)
            .map(datum => [datum.year, datum.value])
        };

        return (
          <SmallLineChart
            key={area}
            title={chartTitle}
            marginLeft={index === 0 ? 60 : 0}
            width={index === 0 ? 160 : 100}
            yAxis={{
              title: index === 0 ? props.yAxisTitle : undefined,
              minimum: 0,
              maximum: maximumValue,
              showLabels: index === 0
            }}
            series={[series]}
            tooltipFormatter={props.tooltipFormatter}
            className={props.classes.smallLineChart}
          />
        );
      })}
    </PanelChart>
  );
};

ChangeByGniGroupChart.propTypes = {
  database: databasePropType,
  yAxisTitle: PropTypes.string,
  indicatorId: PropTypes.number.isRequired,
  methodId: PropTypes.number,
  tooltipFormatter: PropTypes.func
};

export default withStyles(styles)(ChangeByGniGroupChart);
