import React from "react";
import { databasePropType } from "../../../propTypes";
import { formatValue } from "../../../utilities";
import GniGroupBySectorChart from "../charts/GniGroupBySectorChart";

const CurrentSpendingChart = props => (
  <GniGroupBySectorChart
    database={props.database}
    indicatorId={2}
    sectorIds={new Set([1, 2, 4, 5])}
    seriesNames={[
      "Donor",
      "Government",
      "Private Subsidized",
      "Private Non-Subsidized"
    ].reverse()}
    reversedStacks={true}
    tooltipFormatter={function() {
      return `${this.series.name} Share of ${
        this.key
      } Spending: <strong>${formatValue(this.percentage / 100, true)}</strong>`;
    }}
  />
);

CurrentSpendingChart.propTypes = {
  database: databasePropType
};

export default CurrentSpendingChart;
